func lookupPath(root any, dotted string) any {
	cur := root
	for _, part := range strings.Split(dotted, ".") {
		if part == "" {
			continue
		}
		m, ok := cur.(map[string]any)
		if !ok {
			return nil
		}
		cur, ok = m[part]
		if !ok {
			return nil
		}
	}
	return cur
}

func ResolveReferences(spec any, workflowInput any, checkpoints map[string]any) any {
	if spec == nil {
		return workflowInput
	}
	switch v := spec.(type) {
	case DataRef:
		expr := v.Expr
		if expr == "${input}" {
			return workflowInput
		}
		if strings.HasPrefix(expr, "${input.") && strings.HasSuffix(expr, "}") {
			return lookupPath(workflowInput, expr[8:len(expr)-1])
		}
		if strings.HasPrefix(expr, "${steps.") && strings.HasSuffix(expr, "}") {
			rest := expr[8 : len(expr)-1]
			parts := strings.Split(rest, ".")
			stepOut := checkpoints[parts[0]]
			if len(parts) <= 2 {
				return stepOut
			}
			return lookupPath(stepOut, strings.Join(parts[2:], "."))
		}
		if expr == "${steps}" {
			return checkpoints
		}
		return expr
	case map[string]any:
		out := make(map[string]any, len(v))
		for k, val := range v {
			out[k] = ResolveReferences(val, workflowInput, checkpoints)
		}
		return out
	case []any:
		out := make([]any, len(v))
		for i, val := range v {
			out[i] = ResolveReferences(val, workflowInput, checkpoints)
		}
		return out
	default:
		return spec
	}
}

