func (ec *ExecutionContext) DedupeKey() string {
	wf := ec.Task.WorkflowID
	if wf == "" {
		wf = ec.Task.ID
	}
	st := ec.Task.StepID
	if st == "" {
		st = ec.Task.Name
	}
	return fmt.Sprintf("%s:%s:%d", wf, st, ec.Task.Attempt)
}

// Heartbeat reports whether cancellation was requested. In a running worker it answers what the last lease renewal
// said without waiting for the gateway; the worker renews every lease on its own. For a step with
// a heartbeat timeout (WithHeartbeat, Task.HeartbeatMs) it also tells the engine the step is alive, at most every
// third of that timeout: the worker's own renewals do not, so a handler that stops calling Heartbeat is timed out.
func (ec *ExecutionContext) Heartbeat() (bool, error) {
	if ec.engineHeartbeat() {
		return true, nil
	}
	if ec.transport != nil {
		return ec.transport.cancelRequested(ec.Task.LeaseToken), nil
	}
	return ec.Client.HeartbeatTask(ec.Ctx, ec.Task.LeaseToken, ec.WorkerID, ec.LeaseTTLMs)
}

// engineHeartbeat sends POST /sdk/tasks/:token/heartbeat for a task with HeartbeatMs (throttled) and answers whether
// the last such call said the run was cancelled. Its errors are swallowed: the next window's beat tries again.
func (ec *ExecutionContext) engineHeartbeat() bool {
	if ec.Task.HeartbeatMs == nil || *ec.Task.HeartbeatMs <= 0 || ec.Client == nil {
		return false
	}
	every := time.Duration(max(100, *ec.Task.HeartbeatMs/3)) * time.Millisecond
	ec.mu.Lock()
	due := ec.lastBeat.IsZero() || time.Since(ec.lastBeat) >= every
	if due {
		ec.lastBeat = time.Now()
	}
	ec.mu.Unlock()
	if due {
		if cancelled, err := ec.Client.HeartbeatTask(ec.Ctx, ec.Task.LeaseToken, ec.WorkerID, ec.LeaseTTLMs); err == nil {
			ec.mu.Lock()
			ec.beatCancel = cancelled
			ec.mu.Unlock()
		}
	}
	ec.mu.Lock()
	defer ec.mu.Unlock()
	return ec.beatCancel
}

func (ec *ExecutionContext) EnqueueJob(in EnqueueJobInput) (string, error) {
	merged := map[string]any{}
	for k, v := range ec.Meta {
		merged[k] = v
	}
	for k, v := range in.Context {
		merged[k] = v
	}
	in.Context = merged
	return ec.Client.EnqueueJob(ec.Ctx, in)
}

